import React, { useState } from "react";
import { Link } from "react-router-dom";
import api from "../../utils/api";
import { useAuth } from "../../context/AuthContext";

export default function Rightbar({ communities, onCommunitiesUpdate }) {
  const { user } = useAuth();
  const [joining, setJoining] = useState({});

  const handleJoin = async (communityId, name) => {
    if (!user) return;
    setJoining(j => ({ ...j, [communityId]: true }));
    try {
      await api.post(`/communities/${communityId}/join`);
      onCommunitiesUpdate && onCommunitiesUpdate();
    } catch {}
    finally { setJoining(j => ({ ...j, [communityId]: false })); }
  };

  const isJoined = (c) => user?.joinedCommunities?.some(jc => (jc._id||jc) === c._id);

  return (
    <aside className="rightbar">
      <div className="widget">
        <div className="widget-title">🏘️ Communities</div>
        {communities.slice(0, 7).map(c => (
          <div key={c._id} className="comm-item">
            <div className="comm-item-left">
              <div className="cdot" style={{background:c.color||"#2563eb"}} />
              <div>
                <Link to={`/c/${c.name}`} className="comm-item-name" style={{textDecoration:"none",color:"#374151"}}>c/{c.name}</Link>
                <div className="comm-item-mems">{c.memberCount || c.members?.length || 0} members</div>
              </div>
            </div>
            {user && (
              <button
                className={`join-btn ${isJoined(c)?"joined":"join"}`}
                onClick={() => handleJoin(c._id, c.name)}
                disabled={joining[c._id]}
              >
                {joining[c._id] ? "..." : isJoined(c) ? "Joined" : "Join"}
              </button>
            )}
          </div>
        ))}
      </div>

      <div className="widget">
        <div className="widget-title">🔥 Trending</div>
        <div className="trending-tags">
          {["#AI","#WebDev","#OpenSource","#UX","#Python","#GameDev","#Security","#Cloud","#React","#Design"].map(t => (
            <span key={t} className="ttag">{t}</span>
          ))}
        </div>
      </div>

      <div className="widget">
        <div className="widget-title" style={{color:"#991b1b"}}>🛡️ Community Guidelines</div>
        <ol className="rules-list">
          <li>Be respectful and kind</li>
          <li>No hate speech or harassment</li>
          <li>No spam or self-promotion</li>
          <li>Stay on topic</li>
          <li>No violent or abusive content</li>
        </ol>
      </div>
    </aside>
  );
}
